import{_ as s,a0 as o,w as l,s as p,ao as u,I as a,x as i,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Ubuntu 16.10 的 Unity 8 上運行老式 Xorg 程序 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 16.10 的 Unity 8 上運行老式 Xorg 程序 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 16.10 的 Unity 8 上運行老式 Xorg 程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 16.10 的 Unity 8 上運行老式 Xorg 程序 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20161024 How to Use Old Xorg Apps in Unity 8 on Ubuntu 16.10","title":"如何在 Ubuntu 16.10 的 Unity 8 上運行老式 Xorg 程序","tag":"201701","desc":""},"relativePath":"201701/20161024 How to Use Old Xorg Apps in Unity 8 on Ubuntu 16.10.md","filePath":"[post].md"}'),d={name:"201701/20161024 How to Use Old Xorg Apps in Unity 8 on Ubuntu 16.10.md"};function b(g,t,y,m,h,U){const e=o("Link");return l(),p("div",null,[t[13]||(t[13]=u('<h1 id="如何在-ubuntu-16-10-的-unity-8-上運行老式-xorg-程序" tabindex="-1">如何在 Ubuntu 16.10 的 Unity 8 上運行老式 Xorg 程序 <a class="header-anchor" href="#如何在-ubuntu-16-10-的-unity-8-上運行老式-xorg-程序" aria-label="Permalink to “如何在 Ubuntu 16.10 的 Unity 8 上運行老式 Xorg 程序”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/unity8-feature-image.jpg" alt="" title="How to Use Old Xorg Apps in Unity 8 on Ubuntu 16.10s"></p><p>隨着 Ubuntu 16.10 的發佈，Unity 8 越來越吸引到了更多人的關注。這是因為在這個大家最愛的 Linux 發行版的最新版本中可以體驗其帶有的試驗性桌面。桌面發行版是人們最熟悉的 Unity 環境，但有一點點不同。它不再使用 X11 圖形技術，Ubuntu 的開發者選擇了另一種截然不同的方式。</p><p>原來，Unity 8 用的是 Mir，這是 Ubuntu 為了在 Linux 上提供顯示服務而做出的努力。這項技術已經在 Ubuntu phone 和平板上大量使用，但是這次新版是我們在桌面環境上第一次見到 Mir 。</p><p>這項技術相當新穎，結果是沒多少 Linux 程序能運行在它之上。不是所有，那也是大部分的程序設計在 Xorg 和 X11 之上運行。如果你想要試試在 Unity 8 上運行這些程序，你肯定會為在 Unity 8上確實能夠運行之前的 Xorg 程序而高興。接下來是如何做！</p><h3 id="登錄進-unity-8" tabindex="-1">登錄進 Unity 8 <a class="header-anchor" href="#登錄進-unity-8" aria-label="Permalink to “登錄進 Unity 8”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/unity8-select-unity-8-login.jpg" alt="unity8-select-unity-8-login" title="unity8-select-unity-8-login"></p><p>Unity 8 在 Ubuntu 16.10 上是一個可選會話。在使用之前只須牢記一件事情：它不會加載 AMD 的圖形驅動，Intel 的同樣不會加載。唯一支持的圖形驅動是 Nvidia 的開源驅動。要用 Unity 8 的話，只要像往常那樣啓動 Ubuntu，然後，在登錄進去之前，點擊用户名上面的 Ubuntu 圖標，選擇 Unity8 選項。如果萬事順利的話，這個新的、試驗性的桌面環境將會加載。</p><p><strong>注意</strong>： Unity 8 非常新而且不穩定，自行承擔使用風險。</p><h3 id="安裝-libertine" tabindex="-1">安裝 Libertine <a class="header-anchor" href="#安裝-libertine" aria-label="Permalink to “安裝 Libertine”">​</a></h3><p>Xorg 程序（例如 Firefox 等）確實能在 Unity 8 上使用，在使用之前需要一點小調整。在 Mir 桌面上用終端打開 Libertine ，在 Scopes 窗口中點擊終端圖標就能完成。一旦打開，輸入你的密碼。接下來，輸入以下的命令：</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/unity8-installing-libertine-in-terminal.jpg" alt="unity8-installing-libertine-in-terminal" title="unity8-installing-libertine-in-terminal"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install libertine-tools libertine-scope libertine</span></span></code></pre></div><p>當這些程序完成安裝後，點擊並拖動 Scopes 窗口以刷新內容。然後，在面板上點擊來啓動 libertine。</p><h3 id="新建-xorg-容器" tabindex="-1">新建 Xorg 容器 <a class="header-anchor" href="#新建-xorg-容器" aria-label="Permalink to “新建 Xorg 容器”">​</a></h3><p>打開 Libertine，就可以新建一些（應用）容器了。這些容器很特別，因為它們能讓基於 X11 的 Linux 程序在 Mir/Unity 8 桌面上的容器之中運行。另外，如果需要支持 32 位應用，勾選“i386 multiarch support”複選框。否則，什麼都不要動（或者輸入名字和密碼），點擊“OK”。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/unity8-libertine-create-new-container.jpg" alt="unity8-libertine-create-new-container" title="unity8-libertine-create-new-container"></p><p>在這之後，這個 Xorg 容器就準備好，可以使用了。在 Libertine 找到它並啓動。刪除也很容易，右鍵點擊容器，選擇“刪除”選項。</p><p><strong>注意</strong>：每一個 Xorg 容器有 500 MB的最大內存限制。所以多個容器是有必要的。</p><h3 id="安裝軟件" tabindex="-1">安裝軟件 <a class="header-anchor" href="#安裝軟件" aria-label="Permalink to “安裝軟件”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/unity8-libertine-install-software.jpg" alt="unity8-libertine-install-software" title="unity8-libertine-install-software"></p><p>在 Libertine 容器中安裝軟件有兩個方法。第一種是允許用户啓動容器後選擇“輸入包名或者 Debian 文件”，這意味着用户可以在軟件中心或者終端找到一個軟件的名字，然後在 Libertine 中輸入它來安裝。也可以指定特定的 DEB 文件來安裝，可以在Libertine LXC 容器中直接搜索安裝包。</p><p><strong>注意</strong>：Unity 8 非常新，一些程序或許不能在 Libertine 里加載或者完全安裝。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>Unity 8 展現了不少的新特性，它現代、時髦，而且比之前任何一個 Unity 迭代版本都快。唯一限制它的就是使用率。事實是大部分用户更樂意選擇實用的應用程序，而不是一個別致新穎的桌面環境。某種程度上來説，使用 Libertine 能解決這個問題，但它不會永久有效。早晚有一天，Canonical 都需要自行移植這些程序或者向社區求助來徹底解決這個問題。</p><hr>',26)),a("p",null,[t[1]||(t[1]=i("via: ",-1)),n(e,{href:"https://www.maketecheasier.com/use-old-xorg-apps-unity-8/"},{default:r(()=>[...t[0]||(t[0]=[i("https://www.maketecheasier.com/use-old-xorg-apps-unity-8/",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=i("作者：",-1)),n(e,{href:"https://www.maketecheasier.com/author/derrikdiener/"},{default:r(()=>[...t[2]||(t[2]=[i("Derrik Diener",-1)])]),_:1}),t[6]||(t[6]=i(" 譯者：",-1)),n(e,{href:"https://github.com/ypingcn"},{default:r(()=>[...t[3]||(t[3]=[i("ypingcn",-1)])]),_:1}),t[7]||(t[7]=i(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[8]||(t[8]=[i("LCTT",-1)])]),_:1}),t[11]||(t[11]=i(" 組織編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:r(()=>[...t[9]||(t[9]=[i("Linux中國",-1)])]),_:1}),t[12]||(t[12]=i(" 榮譽推出",-1))])])}const k=s(d,[["render",b]]);export{x as __pageData,k as default};
